const root = '/Users/anandarora/Veyra';
const work = root + '/.work/veyra-competitive-research';
const out = root + '/outputs/veyra-product-review';
const items = [
{id:'mabl',name:'mabl',category:'AI-native low-code continuous testing'},
{id:'testim',name:'Tricentis Testim',category:'AI-stabilized low-code browser testing; focus on Testim, not all Tricentis products'},
{id:'autify',name:'Autify',category:'no-code/AI browser testing; distinguish current named product variants and rebrands'},
{id:'katalon',name:'Katalon',category:'broad low-code automation platform; distinguish Studio and execution/cloud add-ons'},
{id:'ghost-inspector',name:'Ghost Inspector',category:'codeless recorded browser testing'},
{id:'functionize',name:'Functionize',category:'enterprise AI test automation'},
{id:'momentic',name:'Momentic',category:'AI-native browser testing with local/developer workflows'},
{id:'testrigor',name:'testRigor',category:'plain-English intent-based automation'},
{id:'virtuoso',name:'Virtuoso QA',category:'natural-language and semantic/context-aware test automation'},
{id:'testsigma',name:'Testsigma',category:'AI-powered low-code test automation'},
{id:'qa-wolf',name:'QA Wolf',category:'managed test automation service; separate service outcomes from software features'},
{id:'rainforest-qa',name:'Rainforest QA',category:'no-code/AI browser QA; verify present product and pricing model'},
{id:'spur',name:'Spur AI QA testing',category:'AI-native application testing; disambiguate from unrelated Spur businesses'},
{id:'browserstack',name:'BrowserStack Low Code Automation',category:'low-code browser testing within BrowserStack; avoid attributing unrelated suite features without evidence'},
{id:'reflect',name:'Reflect browser test automation',category:'no-code/AI browser testing; verify ownership, active availability and latest pricing'},
{id:'qa-tech',name:'QA.tech',category:'AI exploratory/autonomous browser testing'}
];
const schema = JSON.stringify({type:'object',properties:{id:{type:'string'},name:{type:'string'},product_status:{type:'string'},category:{type:'string'},target_user:{type:'string'},distinctive_features:{type:'array',items:{type:'string'}},pricing_summary:{type:'string'},pricing_unit:{type:'string'},pricing_conditions:{type:'string'},pricing_status:{type:'string'},local_privacy_governance:{type:'string'},moat_assessment:{type:'string'},moat_strength:{type:'string'},limitations:{type:'array',items:{type:'string'}},veyra_implication:{type:'string'},sources:{type:'array',items:{type:'object',properties:{url:{type:'string'},title:{type:'string'},supports:{type:'string'},evidence_type:{type:'string'}},required:['url','title','supports','evidence_type']}},report_path:{type:'string'}},required:['id','name','product_status','category','target_user','distinctive_features','pricing_summary','pricing_unit','pricing_conditions','pricing_status','local_privacy_governance','moat_assessment','moat_strength','limitations','veyra_implication','sources','report_path']});
const context = 'Research date: 6 October 2026 (session date). Veyra is a local-first Electron browser QA product aimed at manual/low-code testers. Its proposed loop is Teach -> Test -> Results, with explicit assertions, parameterized reusable semantic business modules, evidence-backed PASS/FAIL/BLOCKED and human-governed AI suggestions. Its long-term Application Behaviour Model (ABM) would connect business intent, inputs/outputs, states, dependencies, approved rules, failures and risk. This is a thesis, not a proven moat or fully shipped product. V0 excludes API testing, multi-browser, CI, scheduling, parallel runs, autonomous exploration and full self-healing. User wants thorough current competitive features, pricing, moats/defensibility, and real opportunity/need gaps. Treat unique as distinctive unless exclusivity is actually established. Do not invent Manus credit usage or pricing; that policy concerns Manus only, not competitor product pricing.';
const rules = 'Use available functions.search for external research, then fetch multiple public full-text sources (prefer fetch over interactive browser). Do not rely on snippets alone. Prefer official product docs/pricing for availability and exact terms; triangulate important claims with credible independent sources where obtainable. Check current product status, rebranding/acquisitions and older pricing contradictions. Record URLs and evidence in your assigned working report as findings emerge. State whether a claim is vendor-marketed, documented capability, independently supported or analyst inference. A public webpage is not a hands-on benchmark. Do not interpret missing public documentation as feature absence. Keep search focused and stop once material questions are resolved or evidence is clearly unavailable. If a page is blocked or interactive tools unavailable, record the limitation and do not fabricate reading it. No signups, trials requiring accounts, outreach, purchases, or running products. Never edit application code, PRD, tasks.md, status_quo.md or groundrules; only write your assigned research working file. No tests, npm, builds, dev servers or Reticle. Jev is not suited to this heterogeneous open-ended research; use research reasoning, no Jev calls or savings claims. Follow the deep-research writing requirements: full useful paragraphs, no tables unless expressly requested, factual claims cited near text as [1] with References definitions in exact form [1]: https://url "Descriptive title". Do not add generic executive-summary/method sections. Distinguish evidence from assessment next to each affected claim. Do not run another workflow or spawn further agents.';
const mappedPromise = parallel('Research competitor features, pricing and defensibility', () => items.map((item,index) => agent(context + '\n\nResearch exactly ONE competitor: '+item.name+'. Focus: '+item.category+'.\n'+rules+'\n\nProvide: (1) active product identity and intended customer; (2) distinctive capabilities and mechanism, compared to category baseline but not broad independent research into other vendors; (3) CURRENT official pricing/free/trial information including currency, per-user/workspace/test/execution/minute/concurrency unit, monthly versus annual billing, included quotas, overages and product add-ons. If sales-only, explicitly say quote-based; do NOT estimate private contract prices. Do not treat a monthly annual-commitment equivalent as a true monthly subscription, or an example quote/review as list price. Retain older contradicted price only with date and caveat if material. (4) recorder/intent authoring, assertions/test oracle, reusable modules and semantic contracts, datasets, self-healing approval controls, diagnostics/evidence, historical defect memory/coverage concepts, local execution vs cloud AI processing (do not conflate local browser with offline/private AI), portability/export/lock-in; mark unverified dimensions; (5) plausible moat MECHANISMS, such as accumulated learned artifacts, switching costs, distribution, proprietary infrastructure, operating capability. Grade qualitative emerging/moderate/strong/unproven with reasons and uncertainty. Funding, generic LLM access and feature count alone are NOT moats. (6) supported limitations versus inference and fit/risk for Veyra; (7) evidence URLs and material gaps. Include meaningful details for a thorough evaluation, avoiding repetitive marketing fluff. Save your completed detailed profile to '+work+'/competitors/'+String(index+1).padStart(2,'0')+'-'+item.id+'.md. Return the schema, exact path and enough structured details/cited sources for synthesis; do not return only a generic summary.',{brief:'Research '+item.name+' features, pricing and moat',sandbox:'shared',effort_level:'lite'})),{schema});
const marketPromise = agent(context+'\n\nYour ONE subject is buyer needs and unmet demand in browser regression/AI QA, not separate competitor dossiers.\n'+rules+'\n\nFind credible recent practitioner/survey/research evidence on repetitive manual regression, automation adoption barriers, flaky tests and maintenance, test-oracle correctness/false confidence, privacy and cloud AI data handling, cost predictability, fragmented quality knowledge, onboarding and nontechnical collaboration. Distinguish vendor-sponsored survey evidence from independent evidence; record actual study year, sample and denominator for any statistics, or omit unsupported percentages. Evaluate open-source/coded Playwright and Cypress plus AI coding assistants and continued manual testing as economic substitutes at a category level; do not pretend free license means free total cost. Look for contrary evidence: buyers already well served, demand for cloud CI over desktop, and why local-first or broad ABM complexity might not sell. Assess plausible segments (manual-heavy commerce/SaaS teams, QA agencies, privacy-sensitive teams) but avoid invented market size or willingness to pay. Identify the evidence-backed PAIN separately from a hypothesized unmet SOLUTION. Describe a small number of prioritized need gaps with buyer, job, current workaround, why existing approaches may fall short, payment rationale, adoption risk, and falsification/validation tests. Public research cannot prove demand; say what requires interviews or pilots. Save detailed cited findings as '+work+'/market/buyer-needs.md and return structured results.',{brief:'Research buyer needs, unmet demand and coded substitutes',sandbox:'shared',effort_level:'standard',schema:JSON.stringify({type:'object',properties:{report_path:{type:'string'},supported_pains:{type:'array',items:{type:'string'}},opportunity_hypotheses:{type:'array',items:{type:'string'}},counterevidence:{type:'array',items:{type:'string'}},substitute_economics:{type:'string'},sources:{type:'array',items:{type:'object',properties:{url:{type:'string'},title:{type:'string'},supports:{type:'string'},evidence_type:{type:'string'}},required:['url','title','supports','evidence_type']}}},required:['report_path','supported_pains','opportunity_hypotheses','counterevidence','substitute_economics','sources']})});
const [mapped,market] = await Promise.all([mappedPromise,marketPromise]);
const successful = mapped.filter(r=>r.ok).map(r=>r.value);
const failures = mapped.map((r,i)=>r.ok?null:{item:items[i].name,code:r.error.code,message:r.error.message}).filter(Boolean);
if(!market.ok) failures.push({item:'Buyer needs',code:market.error.code,message:market.error.message});
log('Collected '+successful.length+' competitor profiles; '+failures.length+' research failures. Synthesizing evidence.');
const reduced = await agent(context+'\n\nYou are the sole cross-item synthesis agent. Use the collected structured results and the completed working profiles at their report_path; do not repeat competitor research or spawn agents. Read supplied local context files and existing baseline when useful. Your input results:\n'+JSON.stringify({competitors:successful,market:market.ok?market.value:null,failures})+'\n\nCreate a thorough, readable final evaluation answering unique/distinctive features, pricing and each product\'s moat, then real opportunities and need gaps for Veyra. Important: do not overstate an ABM as globally unique, assume missing documentation means absence, confuse vendor claims with demonstrated reliability, or promote recommendations into approved Veyra scope. Start with concrete conclusion answering what opportunity exists, not a generic executive summary or methodology section. Explain category groups, table stakes and dangerous false differentiators. Include a substantive named section for EACH successfully researched competitor with buyer fit, distinctive mechanism, pricing (all material units/annual terms/quotas/add-ons), defensibility reason and limits, and Veyra implication. Do not simply concatenate marketing notes. A quote-only product has no numeric public list price: say so; do not invent estimates. Include strengths of already well-served segments and why Veyra should not compete on breadth or generic agentic QA. Explicitly contrast goal/semantic/contextual features from testRigor, Virtuoso, Momentic and other findings against Veyra\'s proposed model and claims. Treat moat as inference unless supporting independent evidence exists. Rank a small set of opportunities qualitatively with evidence, buyer/job/current workaround, underserved aspect, competition, commercial rationale, technical/distribution risk, falsification tests and which aspects fit V0 versus later; avoid artificial scores or invented market-size/WTP estimates. Consider maintenance fan-out, contract-level test correctness, historical incident knowledge, privacy/offline governance and transparent economics, but allow evidence to overturn the thesis. A gap should be a demonstrable workflow disadvantage, not a feature missing from one website. Include a minimal pilot/measurement proposal as validation, not an implementation commitment. Summarize contradictions/updates relative to existing docs/02_Competitive_Validation.md with citations rather than silently rewriting it. Do not promise continuous testing in V0. State research date and public-evidence limitations near relevant statements, and include explicit unresearched notable market adjacency in one concise sentence if helpful—coverage is selected not exhaustive.\n\nWriting: detailed enough to be thorough, no arbitrary word target, connected paragraphs, restrained bullets, no Markdown tables because user has not explicitly requested tables. Cite factual/source-derived claims near text using numbered [1] citations and exactly [1]: https://url "Source title" definitions in References; assign unique reusable IDs across full report. Keep uncertainty beside affected claims, no generic research-boundary sections. No standalone post-draft validation scripts/logs. Correct one material issue if encountered, not endless review.\n\nWrite final report to '+out+'/02_competitive_research.md. Also write a reusable properly quoted UTF-8 CSV to '+out+'/03_competitor_comparison.csv with one row per competitor and columns product,category,product_status,target_user,distinctive_features,public_pricing,pricing_unit,billing_terms_quotas_addons,pricing_evidence_status,local_execution_ai_privacy_governance,moat_strength_inference,moat_mechanism_and_limits,veyra_implication,source_urls,research_date. Use full details rather than reducing quote-based prices to 0. Do not present CSV as normalized total-cost comparison. Only write these two final deliverables; never edit source docs/tasks/PRD or app code.\nReturn exact paths, concise substantive conclusions, pricing caveats and any coverage failures.',{brief:'Synthesize competitive evaluation and Veyra opportunity gaps',sandbox:'shared',effort_level:'standard',input_files:[{path:root+'/README.md',name:'veyra-readme'},{path:root+'/status_quo.md',name:'current-project-state'},{path:root+'/docs/02_Competitive_Validation.md',name:'prior-competitive-validation'},{path:out+'/01_first_pass.md',name:'first-pass-assessment'}],schema:JSON.stringify({type:'object',properties:{report_path:{type:'string'},comparison_csv_path:{type:'string'},main_conclusions:{type:'array',items:{type:'string'}},pricing_caveats:{type:'array',items:{type:'string'}},coverage_failures:{type:'array',items:{type:'string'}},source_count:{type:'integer'}},required:['report_path','comparison_csv_path','main_conclusions','pricing_caveats','coverage_failures','source_count']})});
return {competitors:successful,market:market.ok?market.value:null,failures,final:reduced.ok?reduced.value:null,synthesis_error:reduced.ok?null:reduced.error};

